&lt;table class=&quot;Bestiaire&quot;&gt;
&lt;tr&gt;
&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Troll mythique&lt;div style=&quot;float:right;&quot;&gt;FP 6/RMy 2&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Humano&#239;de&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Humano&#239;de.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Montagnes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Montagnes.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Froid&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Froid.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Campagnes mythiques p.218&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; 2 400
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;Humano&#239;de&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-G&#233;ant.html&quot; title=&quot;G&#233;ant (sous-type)&quot;&gt;g&#233;ant&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Mythique.html&quot; title=&quot;Mythique (sous-type)&quot;&gt;mythique&lt;/a&gt;) de taille G, CM
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +2 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;Vision dans le noir (Ext ou Sur)&quot;&gt;vision dans le noir&lt;/a&gt; &#224; 18 m, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;vision nocturne&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Odorat-(Capacit&#233;).html&quot; title=&quot;Odorat (Ext)&quot;&gt;odorat&lt;/a&gt; ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +8
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 18, contact 11, pris au d&#233;pourvu 16 (+2 Dex, +7 naturelle, -1 taille)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 79 (6d8+52) ; &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;g&#233;n&#233;ration-(Capacit&#233;).html&quot; title=&quot;R&#233;g&#233;n&#233;ration (Ext)&quot;&gt;r&#233;g&#233;n&#233;ration&lt;/a&gt; 5 (acide ou feu, cf. vitalit&#233; primitive)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +4, &lt;b&gt;Vig&lt;/b&gt; +11, &lt;b&gt;Vol&lt;/b&gt; +3
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Capacit&#233;s d&#233;fensives&lt;/b&gt; vitalit&#233; primitive ; &lt;b&gt;RD&lt;/b&gt; 5/&lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Rdepique.html&quot; title=&quot;RD&#233;pique&quot;&gt;&#233;pique&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 9 m
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; morsure, +9 (1d8+6) et 2 griffes, +9 (1d6+6)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Espace occup&#233;&lt;/b&gt; 3 m ; &lt;b&gt;Allonge&lt;/b&gt; 3 m
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;&#201;ventration-(Capacit&#233;).html&quot; title=&quot;&#201;ventration (Ext)&quot;&gt;&#233;ventration&lt;/a&gt; (2 griffes, 1d6+9 plus &lt;a class=&quot;pagelink&quot; href=&quot;Saignement-(Capacit&#233;).html&quot; title=&quot;Saignement (Ext)&quot;&gt;saignement&lt;/a&gt; 5 plus sauvagerie f&#233;roce), &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoir-Mythique-(Capacit&#233;).html&quot; title=&quot;Pouvoir mythique (Sur) &amp;#91;Mythique&amp;#93;&quot;&gt;pouvoir mythique&lt;/a&gt; (2/jour, &lt;a class=&quot;pagelink&quot; href=&quot;Mont&#233;e-En-Puissance-(Capacit&#233;).html&quot; title=&quot;Mont&#233;e en puissance (Sur) &amp;#91;Mythique&amp;#93;&quot;&gt;mont&#233;e en puissance&lt;/a&gt; +1d6), &lt;a class=&quot;pagelink&quot; href=&quot;Sauvagerie-F&#233;roce-(Capacit&#233;).html&quot; title=&quot;Sauvagerie f&#233;roce (Sur) &amp;#91;Mythique&amp;#93;&quot;&gt;sauvagerie f&#233;roce&lt;/a&gt; (&#233;ventration)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 23, &lt;b&gt;Dex&lt;/b&gt; 14, &lt;b&gt;Con&lt;/b&gt; 23, &lt;b&gt;Int&lt;/b&gt; 6, &lt;b&gt;Sag&lt;/b&gt; 9, &lt;b&gt;Cha&lt;/b&gt; 6
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +4, &lt;b&gt;BMO&lt;/b&gt; +11, &lt;b&gt;DMD&lt;/b&gt; 23
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Force-Intimidante.html&quot; title=&quot;Force intimidante&quot;&gt;Force intimidante&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Talent.html&quot; title=&quot;Talent&quot;&gt;Talent&lt;/a&gt; (Perception), &lt;a class=&quot;pagelink&quot; href=&quot;Volont&#233;-De-Fer.html&quot; title=&quot;Volont&#233; de fer&quot;&gt;Volont&#233; de fer&lt;/a&gt;&lt;sup&gt;M&lt;/sup&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; +10, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +8
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; g&#233;ant
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;&#201;cologie&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Environnement&lt;/b&gt; montagnes froides
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Organisation sociale&lt;/b&gt; solitaire ou gang (2-4)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Tr&#233;sor&lt;/b&gt; standard
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Pouvoirs sp&#233;ciaux&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Vitalit&#233; primitive (Sur).&lt;/b&gt; Quand le troll mythique re&#231;oit des d&#233;g&#226;ts lors d’un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;, sa r&#233;g&#233;n&#233;ration augmente de 5 au d&#233;but de son prochain tour jusqu’&#224; un maximum de 25. S’il est au maximum de ses points de vie au d&#233;but de son tour, sa r&#233;g&#233;n&#233;ration d&#233;cro&#238;t de 5 jusqu’&#224; un minimum de 5. Le fait de blesser un troll avec de l’acide ou du feu ne fait qu’annuler partiellement sa r&#233;g&#233;n&#233;ration. Lors de son tour, apr&#232;s avoir re&#231;u ces d&#233;g&#226;ts, le troll ne r&#233;g&#233;n&#232;re que de la moiti&#233; du nombre normal de points de vie (par exemple, un troll ayant une r&#233;g&#233;n&#233;ration de 15 ne gu&#233;rirait que de 7 points de vie) et peut mourir normalement lors de ce round.
&lt;/div&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;td&gt;
&lt;div&gt;
&lt;i&gt;Cet humano&#239;de g&#233;ant est dot&#233; d’&#233;normes d&#233;fenses. Sa peau verte est couverte de verrues et d’excroissances osseuses et ses avant-bras sont encore plus &#233;pais encore que ses jambes, d&#233;j&#224; tr&#232;s charnues.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;
La peau du troll mythique est presque aussi dure que la pierre et il arbore des excroissances osseuses, des pointes ornementales sur la t&#234;te et des dents surdimensionn&#233;es qui rendent son visage encore plus grotesque qu’il ne l’est d&#233;j&#224;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Scrag (FP 6/RMy 2)&lt;a class=&quot;headeranchor&quot; id=&quot;Scrag_FP_GRMy_C_0&quot; href=&quot;#Scrag_FP_GRMy_C_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;La vitalit&#233; primitive du &lt;a class=&quot;pagelink&quot; href=&quot;Troll.html&quot; title=&quot;Troll&quot;&gt;scrag&lt;/a&gt; mythique s’active m&#234;me s’il n’est pas dans l’eau et devrait normalement &#234;tre incapable d’utiliser son pouvoir de &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;g&#233;n&#233;ration-(Capacit&#233;).html&quot; title=&quot;R&#233;g&#233;n&#233;ration (Ext)&quot;&gt;r&#233;g&#233;n&#233;ration&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Troll de mousse (FP 4/RMy 1)&lt;a class=&quot;headeranchor&quot; id=&quot;Troll_de_mousse_FP_ERMy_B_1&quot; href=&quot;#Troll_de_mousse_FP_ERMy_B_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le &lt;a class=&quot;pagelink&quot; href=&quot;Troll-De-Mousse.html&quot; title=&quot;Troll de mousse&quot;&gt;troll de mousse&lt;/a&gt; mythique gagne &lt;a class=&quot;pagelink&quot; href=&quot;F&#233;rocit&#233;-(Capacit&#233;).html&quot; title=&quot;F&#233;rocit&#233; (Ext)&quot;&gt;f&#233;rocit&#233;&lt;/a&gt; et vitalit&#233; primitive comme aptitudes mythiques.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Troll de pierre (FP 7/RMy 3)&lt;a class=&quot;headeranchor&quot; id=&quot;Troll_de_pierre_FP_HRMy_D_2&quot; href=&quot;#Troll_de_pierre_FP_HRMy_D_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le &lt;a class=&quot;pagelink&quot; href=&quot;Troll-De-Pierre.html&quot; title=&quot;Troll de pierre&quot;&gt;troll de pierre&lt;/a&gt; mythique gagne &lt;a class=&quot;pagelink&quot; href=&quot;Saignement-(Capacit&#233;).html&quot; title=&quot;Saignement (Ext)&quot;&gt;saignement&lt;/a&gt; 5 (avec &lt;a class=&quot;pagelink&quot; href=&quot;&#201;ventration-(Capacit&#233;).html&quot; title=&quot;&#201;ventration (Ext)&quot;&gt;&#233;ventration&lt;/a&gt;) et vitalit&#233; primitive. Il peut d&#233;penser une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoir-Mythique-(Capacit&#233;).html&quot; title=&quot;Pouvoir mythique (Sur) &amp;#91;Mythique&amp;#93;&quot;&gt;pouvoir mythique&lt;/a&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt; pour ignorer la p&#233;trification due &#224; la lumi&#232;re du soleil pendant 1 minute.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Troll des glaces (FP 5/RMy 2)&lt;a class=&quot;headeranchor&quot; id=&quot;Troll_des_glaces_FP_FRMy_C_3&quot; href=&quot;#Troll_des_glaces_FP_FRMy_C_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le &lt;a class=&quot;pagelink&quot; href=&quot;Troll-Des-Glaces.html&quot; title=&quot;Troll des glaces&quot;&gt;troll des glaces&lt;/a&gt; mythique gagne &lt;a class=&quot;pagelink&quot; href=&quot;Saignement-(Capacit&#233;).html&quot; title=&quot;Saignement (Ext)&quot;&gt;saignement&lt;/a&gt; 5 (quand il utilise &lt;a class=&quot;pagelink&quot; href=&quot;&#201;ventration-(Capacit&#233;).html&quot; title=&quot;&#201;ventration (Ext)&quot;&gt;&#233;ventration&lt;/a&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Sauvagerie-F&#233;roce-(Capacit&#233;).html&quot; title=&quot;Sauvagerie f&#233;roce (Sur) &amp;#91;Mythique&amp;#93;&quot;&gt;sauvagerie f&#233;roce&lt;/a&gt; (&#233;ventration) et vitalit&#233; primitive comme aptitudes mythiques.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Troll j&#246;tun (FP 18/RMy 7)&lt;a class=&quot;headeranchor&quot; id=&quot;Troll_j&#246;tun_FP_BIRMy_H_4&quot; href=&quot;#Troll_j&#246;tun_FP_BIRMy_H_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le &lt;a class=&quot;pagelink&quot; href=&quot;Troll-J&#246;tun.html&quot; title=&quot;Troll j&#246;tun&quot;&gt;troll j&#246;tun&lt;/a&gt; mythique gagne &lt;a class=&quot;pagelink&quot; href=&quot;Saignement-(Capacit&#233;).html&quot; title=&quot;Saignement (Ext)&quot;&gt;saignement&lt;/a&gt; 5 (avec morsure), &lt;a class=&quot;pagelink&quot; href=&quot;Blocage-Des-Attaques-(Capacit&#233;).html&quot; title=&quot;Blocage des attaques (Ext)&quot;&gt;blocage des attaques&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sauvagerie-F&#233;roce-(Capacit&#233;).html&quot; title=&quot;Sauvagerie f&#233;roce (Sur) &amp;#91;Mythique&amp;#93;&quot;&gt;sauvagerie f&#233;roce&lt;/a&gt; (attaque &#224; outrance), &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fense-(Capacit&#233;).html&quot; title=&quot;D&#233;fense (Ext)&quot;&gt;d&#233;fense&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;F&#233;rocit&#233;-(Capacit&#233;).html&quot; title=&quot;F&#233;rocit&#233; (Ext)&quot;&gt;f&#233;rocit&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Immunit&#233;-(Capacit&#233;).html&quot; title=&quot;Immunit&#233; (Ext ou Sur)&quot;&gt;immunit&#233;&lt;/a&gt; &#224; l’acide et au froid et vitalit&#233; primitive.
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
